(7527661, 1203041, 28742, '<td valign="top">Congrats, Paul! Another fine image of a fantastical location.</td>', 'Congrats, Paul! Another fine image of a fantastical location.', '2017-08-08 02:00:23.000000', NULL, 0),
(7527662, 1203246, 185773, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mariuca:</b></div><hr/><i> great capture and composition of a warrior - better not meet in person </i></td></tr></table> <br/> <br/>Hi Mariuca, very thankful for your comment, I was contemplating should Icrop nearer due to the long horn as it stretch them out.  I decided it better to keep them in the end to take the original composition.  Really appreciate toy support and feedback.<br/> <br/>Best regards,<br/> <br/>Roger New.</td>', 'Originally posted by mariuca: great capture and composition of a warrior - better not meet in person   Hi Mariuca, very thankful for your comment, I was contemplating should Icrop nearer due to the long horn as it stretch them out.  I decided it better to keep them in the end to take the original composition.  Really appreciate toy support and feedback. Best regards, Roger New.', '2017-08-08 02:01:22.000000', NULL, 0),
(7527663, 1203246, 28742, '<td valign="top">WOW! Give me the name of his planet so I can put it on my list of places to avoid. ;-) Stunning macro. Mesmerizing. Congratulations on 4th.</td>', 'WOW! Give me the name of his planet so I can put it on my list of places to avoid. ;-) Stunning macro. Mesmerizing. Congratulations on 4th.', '2017-08-08 02:02:40.000000', NULL, 0),
